sql:
select insert_project_process_step as id from flow.insert_project_process_step(:projectId::integer, :processStepId::integer, :userPositionId::integer, :userId::integer, :companyId::integer);
select from flow.delete_project_process_step(:projectProcessStepId);
select * from flow.get_pps_with_actions_and_requirements(:stepId::integer)
select a.id, a.size, a.date_created, a.date_modified, a.filename, a.attachment_type_id, a.content_type, a.s3_key from flow.project_process_step_attachment ppsa inner join flow.attachment a on a.id = ppsa.attachment_id where ppsa.project_process_step_id = :projectProcessStepId
insert into flow.project_process_step_attachment(attachment_id, project_process_step_id, created_by_id) values (:attachmentId, :projectProcessStepId, :createdById)
select from flow.update_project_process_step_status(:projectId::integer, :processStepId::integer, :projectProcessStepId::integer, :main::boolean, :companyProcessStepStatusTypeId::integer, :processStepStatusTypeId::integer, :userId::integer) -- update flow.project_process_step -- set -- company_process_step_status_type_id = :companyProcessStepStatusTypeId, -- main = :main, -- modified_by_id = :userId, -- date_modified = now(), -- process_step_complete_date = ( -- case when :processStepStatusTypeId = 2 then now() end) -- where id = :projectProcessStepId;
with positions as ( select array( select pspop.position_id from flow.process_step_process_owning_position pspop where pspop.process_step_process_id = :processStepProcessId ) as position_ids ) select u.id as user_id, u.first_name, u.last_name, u.first_name || ' ' || u.last_name as full_name, up.id as user_position_id, p.position from positions inner join flow.user_position up on array[up.position_id] <@ positions.position_ids inner join flow.user u on u.id = up.user_id inner join flow.position p on p.id = up.position_id inner join flow.company_user_status_type cust on cust.company_id = p.company_id inner join flow.user_status_type ust on ust.company_user_status_type_id = cust.id and ust.user_id = u.id where cust.has_access is true and up.start_date <= now() and (up.end_date is null or up.end_date >= now()) order by u.last_name, u.first_name;
update flow.project_process_step set user_position_id = :userPositionId, modified_by_id = :userId, date_modified = now() where id = :projectProcessStepId
select user_position_id from flow.project_process_step where id = :projectProcessStepId
-- Had to break up this into 2 queries. Still not sure why the single query stopped working
update flow.project_process_step set main = false where flow.project_process_step.project_id = :projectId and flow.project_process_step.process_step_id = :processStepId;
update flow.project_process_step set main = true where flow.project_process_step.id = :projectProcessStepId
select pps.* from flow.project_process_step pps inner join flow.company_process_step_status_type cppsst on cppsst.id = pps.company_process_step_status_type_id where pps.project_id = :projectId and cppsst.process_step_status_type_id = 1 and pps.main is true and pps.archived is not true
insert into flow.project_process_step_action (project_process_step_id, process_step_action_id, triggered_automatically, created_by_id) values (:ppsId, :psaId, :autoTriggered, :createdById)
select count(pps.id) from flow.project_process_step pps inner join flow.company_process_step_status_type cpsst on cpsst.id = pps.company_process_step_status_type_id where pps.project_id = :projectId and pps.process_step_id = :processStepId and pps.archived is not true and cpsst.process_step_status_type_id = 1
with projects as ( select array_agg(p.id) as ids from flow.project p inner join flow.company_project_status_type cpst on cpst.id = p.company_project_status_type_id where case when :contactId::integer is not null then p.contact_id = :contactId else p.contact_id = 0 end and cpst.project_status_type_id = 1 ) select distinct pps.id from projects, flow.project_process_step pps inner join flow.process_step ps on ps.id = pps.process_step_id inner join flow.process_step_action psa on psa.process_step_id = ps.id inner join flow.process_step_requirement psr on psr.process_step_id = ps.id inner join flow.custom_field_group_assignment cfga on cfga.id = psr.custom_field_group_assignment_id inner join flow.company_process_step_status_type cpsst on cpsst.id = pps.company_process_step_status_type_id where case when :contactId::integer is not null then pps.project_id = any(projects.ids) else pps.project_id = :projectId end and pps.archived is not true and cpsst.process_step_status_type_id = 1 and pps.main is true and psr.custom_field_group_assignment_id in (:cfgaIds) and psr.archived is not true and psa.archived is not true and psa.trigger_automatically is true
